def quicksort(arr):
    """This function takes an array as parameter and sorts it in-place"""
    if len(arr) <= 1:
        return
    pivot = arr[0]
    left, right = [], []
    for i in range(1, len(arr)):
        if arr[i] < pivot:
            left.append(arr[i])
        else:
            right.append(arr[i])
    quicksort(left)
    quicksort(right)
    arr[:] = left + [pivot] + right</s>

def find_primes_below(n):
    """This function finds all prime numbers between 2 and a given integer"""
    primes = [True] * n
    primes[0], primes[1] = False, False

    # Find prime numbers
    for i, is_prime in enumerate(primes):
      if is_prime:
        for num in range(i*i, n, i):
            primes[num] = False

    # Filter out primes
    return [i for i, prime in enumerate(primes) if prime]</s>

