def nth_to_last_node(head, n):
    left_ptr = head
    right_ptr = head
    for _ in range(n-1):
        if not right_ptr.nextnode:
            raise LookupError('Error: n is larger than the linked list')
        right_ptr = right_ptr.nextnode 
    while right_ptr.nextnode:
        left_ptr = left_ptr.nextnode
        right_ptr = right_ptr.nextnode
    return left_ptr

