def closestInBST(root, target):
  res = root.val
  while root:
    if root.val == target:
      return root.val
    if abs(root.val-target) < abs(res-target):
      res = root.val
    if target < root.val:
      root = root.left
    else:
      root = root.right
  return res</s>

