class LinkedList {
  Node head;
  public void insertNode(int data) { 
    Node new_node = new Node(data); 
    if (head == null) { 
        head = new_node;
        return;
    }
    Node last = head;  
    while (last.next != null) {
        last = last.next;
    }
    last.next = new_node; 
  } 
}

