function getCurrentDateTime() { 
    var date = new Date(); 
    var dd = date.getDate(); 
    var mm = date.getMonth() + 1; 
    var yyyy = date.getFullYear(); 
    var hh = date.getHours(); 
    var min = date.getMinutes(); 
    var sec = date.getSeconds(); 

    if (dd < 10) { 
        dd = '0' + dd; 
    } 

    if (mm < 10) { 
        mm = '0' + mm; 
    } 

    if (min < 10) { 
        min = '0' + min; 
    } 

    if (sec < 10) { 
        sec = '0' + sec; 
    } 

    return dd + '/' + mm + '/' + yyyy + ' ' + hh + ':' + min + ':' + sec; 
} 

