def transpose_matrix(matrix): 
	row = len(matrix) 
	col = len(matrix[0]) 
	transpose = [[0 for j in range(row)] for i in range(col)] 

	for i in range(row): 
		for j in range(col): 
			transpose[j][i] = matrix[i][j] 

