def reverse_linked_list(head):
    if head is None or head.next is None:
        return head
    prev = None
    curr = head
    while curr is not None:
        prev, curr.next, curr = curr, prev, curr.next
    return prev</s>

def find_num_triplets(arr):
    arr.sort()
    count = 0
    for i in range(len(arr) - 2):
        for j in range(i + 1, len(arr) - 1):
            for k in range(j + 1, len(arr)):
                if arr[i] + arr[j] > arr[k]:
                    count += 1
    return count</s>

def fill_matrix_zeros(matrix):
    n, m = len(matrix), len(matrix[0])
    col0_zero = False
    for i in range(n):
        if matrix[i][0] == 0:
            col0_zero = True
        for j in range(1, m):
            if matrix[i][j] == 0:
                matrix[i][0] = 0
                matrix[0][j] = 0

    for i in range(1, n):
        for j in range(1, m):
            if matrix[i][0] == 0 or matrix[0][j] == 0:
                matrix[i][j] = 0

    if matrix[0][0] == 0:
        for j in range(m):
            matrix[0][j] = 0

    if col0_zero:
        for i in range(n):
            matrix[i][0] = 0</s>

