def quick_sort(arr):
    if len(arr) < 2:
        return arr
    else:
        pivot = arr[0]
        i = 1
        for j in range(1, len(arr)):
            if arr[j] < pivot:
                arr[i], arr[j] = arr[j], arr[i]
                i = i + 1
        arr[0], arr[i-1] = arr[i-1], arr[0]
        left = quick_sort(arr[:i-1])
        right = quick_sort(arr[i:])
        return left + [arr[i-1]] + right</s>

